// G2 OD-10 + E1-04 proof — OWN fresh scratch only (b17_u2g_g2_scratch_*).
// Sanctioned functions only (inventoryB17ContentOffline / applyB17ContentOffline
// / parseB17ContentSources / verifyB17* / assertB17Ready). NEVER runs
// scripts/b17-scope-proof.ts (destructive DELETE), the owner's showcase, or any
// ambient .env/DSN. Credentials are generated by the runner and never printed.
//
// Proves, on one isolated database:
//   OD-10 — dry-run inventory ALWAYS rolls back (no temp policies, no ledger
//           row, business hashes unchanged, repeat dry-run is deepEqual);
//           ambiguous/unidentified provenance is REFUSED (unknown source row,
//           unknown import batch, duplicate/invalid targets, before-state
//           drift) with zero writes; real apply preserves every business row
//           (only service_id bindings + the exact service_standards pairs may
//           move) and is idempotent (applied -> verified -> already_applied).
//   E1-04 — constant <-> ledger row <-> B17_CONTENT_SHAPE <-> live STRUCTURE_SQL
//           four-way consistency on fresh apply; every drift (ledger checksum,
//           structure_checksum, version label, live catalog) is REFUSED
//           fail-closed and RESTORE-RECOVERED (assertB17Ready green again).
import assert from 'node:assert/strict';
import pg from 'pg';
import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { getPool, runMigrations } from '../src/db/index.ts';
import {
  applyB17Offline, assertB17Ready, verifyB17Content, STRUCTURE_SQL, B17_SHAPE,
  B17_CONTENT_VERSION, B17_CONTENT_SHAPE, b17ContentSource,
} from '../src/db/b17Readiness.ts';
import {
  inventoryB17ContentOffline, applyB17ContentOffline, parseB17ContentSources,
} from '../src/db/b17ContentMigration.ts';
import { seedG1 } from './b17-domain-g1-fixture.ts';

const args = process.argv.slice(2);
if (!args.includes('--allow-disposable-b17') || existsSync('.env') || process.env.DATABASE_URL
  || process.env.JWT_SECRET
  || Object.keys(process.env).some(k => /^PG(HOST|PORT|USER|PASSWORD|DATABASE|SERVICE)/.test(k)))
  throw new Error('Explicit isolated opt-in required; ambient config refused');
const one = (key: string) => {
  const values = args.filter(a => a.startsWith(`--${key}=`));
  if (values.length !== 1) throw new Error(`One explicit ${key} required`);
  return new URL(values[0].slice(key.length + 3));
};
const url = one('database-url'), oracleUrl = one('oracle-url');
if (!['postgres:', 'postgresql:'].includes(url.protocol) || url.hostname !== '127.0.0.1'
  || !/^\/b17_u2g_g2_scratch_\d+_\d+$/.test(url.pathname) || !url.port || url.search || url.hash
  || url.username !== 'b17domainowner') throw new Error('Only own named loopback scratch accepted');
if (oracleUrl.protocol !== url.protocol || oracleUrl.host !== url.host || oracleUrl.pathname !== url.pathname
  || oracleUrl.username !== 'postgres' || oracleUrl.search || oracleUrl.hash)
  throw new Error('Oracle must be exact same scratch');
process.env.DATABASE_URL = url.toString();
process.env.JWT_SECRET = randomBytes(48).toString('hex');
const pool = getPool();
// Observation/drift runs on the harness ORACLE (postgres superuser): FORCE RLS
// would otherwise hide every business row from a purpose-less app-role query
// and make the preservation hashes vacuous. The APP role stays NOSUPERUSER/
// NOBYPASSRLS and all readiness/apply calls keep using it.
const oracle = new pg.Client({ connectionString: oracleUrl.toString() });
const pass = (label: string) => console.log(`PASS ${label}`);

// Business data that OD-10 must preserve byte-for-byte. service_standards is
// the association table (checked separately: additions of exact pairs only);
// esg_profile/report_settings may move ONLY their service_id binding.
// service_initiatives is deliberately absent: it is INTRODUCED by the content
// activation (it does not exist pre-apply) and this proof seeds no initiative
// selections, so the association tables above cover every binding delta.
const DATA_TABLES = ['clients', 'departments', 'users', 'client_services', 'assignments', 'answers',
  'evaluations', 'approvals', 'actions', 'profile_assessments', 'audit_log', 'review_snapshots',
  'snapshot_notes', 'client_initiatives', 'staff_lists', 'staff_list_rows', 'notifications',
  'evidence_attachments', 'services', 'standards', 'disclosures', 'items', 'item_links',
  'initiatives_library'];
const BINDING_TABLES = ['esg_profile', 'report_settings'] as const;

async function dataHashes(): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const table of DATA_TABLES) {
    // The content delta ADDS actions.service_id (NULL for every pre-existing
    // row): strip it so the hash compares ROW CONTENT, exactly like the
    // sanctioned inventory businessHashes does for association columns.
    const value = table === 'actions' ? "to_jsonb(t)-'service_id'" : 'to_jsonb(t)';
    out[table] = (await oracle.query(
      `SELECT md5(COALESCE(jsonb_agg(${value} ORDER BY ${value}::text)::text,'')) h FROM ${table} t`)).rows[0].h;
  }
  return out;
}
async function bindingHashes(): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const table of BINDING_TABLES)
    out[table] = (await oracle.query(
      `SELECT md5(COALESCE(jsonb_agg(to_jsonb(t)-'service_id' ORDER BY to_jsonb(t)::text)::text,'')) h FROM ${table} t`)).rows[0].h;
  return out;
}
async function maps(): Promise<{ id: string; service_id: string; standard_id: string }[]> {
  return (await oracle.query('SELECT id,service_id,standard_id FROM service_standards ORDER BY id')).rows;
}
// The fingerprint MUST run as the APP role: STRUCTURE_SQL embeds
// owner_is_current/owner_is_session (content_authority), which differ under the
// oracle's `postgres` identity — the constant is defined for the app role.
const shape = async () => (await pool.query(STRUCTURE_SQL)).rows[0].checksum as string;
const ledger = async () => (await oracle.query(
  'SELECT version,checksum,structure_checksum FROM app_schema_versions ORDER BY version')).rows;

try {
  await oracle.connect();
  assert.equal(Math.floor(Number((await oracle.query('SHOW server_version_num')).rows[0].server_version_num) / 10000), 18);
  assert.deepEqual((await pool.query('SELECT rolsuper,rolbypassrls FROM pg_roles WHERE rolname=current_user')).rows[0],
    { rolsuper: false, rolbypassrls: false });
  assert.equal((await pool.query("SELECT count(*)::int n FROM pg_tables WHERE schemaname='public'")).rows[0].n, 0);
  assert.equal((await runMigrations()).success, true);
  const seed = await seedG1();
  const migration = await pool.connect();
  try {
    assert.equal(await applyB17Offline(migration), 'applied');
  } finally { migration.release(); }
  await assertB17Ready();
  pass('OWN empty PG18; NOSUPERUSER/NOBYPASSRLS; offline U1 activation; readiness green');

  // ---- E1-04 four-way constants (static side) ----
  assert.equal(B17_CONTENT_VERSION, 'B17_U2D', 'canonical label unchanged (Tera ruling)');
  const contentSql = readFileSync(new URL('../src/db/b17-content.sql', import.meta.url), 'utf8').replace(/^﻿/, '');
  assert.match(contentSql, /^-- B17_U2D\./, 'b17-content.sql header names the same label');
  assert.match(contentSql, /version='B17_U2D'/, 'b17-content.sql guard names the same label');
  const before = await dataHashes(), bindingsBefore = await bindingHashes(), mapsBefore = await maps();
  const client = await pool.connect();
  try {
    // ---- OD-10 dry-run: ALWAYS rolled back ----
    const inventoryA = await inventoryB17ContentOffline(client, seed.targets, seed.sources);
    assert.equal(await shape(), B17_SHAPE, 'dry-run leaves the U1 structure untouched');
    assert.equal((await oracle.query("SELECT count(*)::int n FROM pg_policies WHERE policyname LIKE 'b17_inventory%'")).rows[0].n, 0,
      'dry-run SELECT-policy DDL rolled back');
    assert.deepEqual(await ledger().then(rows => rows.map(r => r.version)), ['B17_U1'], 'dry-run writes no ledger row');
    assert.deepEqual(await dataHashes(), before, 'dry-run changes no business row');
    assert.deepEqual(await inventoryB17ContentOffline(client, seed.targets, seed.sources), inventoryA,
      'repeat dry-run is deterministic');
    await assert.rejects(() => verifyB17Content(client), /content_required/, 'content still absent after dry-runs');
    pass('OD-10 dry-run ROLLBACK: no temp policies, no ledger row, business hashes unchanged, repeat deepEqual');

    // ---- OD-10 ambiguous/unidentified refusal (zero writes) ----
    const unknownSource = parseB17ContentSources(
      'Standard Code,Disclosure Code,Item Code,Requirement\nUNKNOWN,U,U,Unknown',
      'pillar,department,topic,parameter\nUNKNOWN,U,U,Unknown');
    for (const [input, sources, error] of [
      [seed.targets, unknownSource, /source_unknown/],
      [[{ ...seed.targets[0], griBatchId: 'g2-unknown-batch' }], seed.sources, /lineage_ambiguous/],
      [[{ ...seed.targets[0], clientId: '00000000-0000-4000-8000-000000000000' }], seed.sources, /client_missing/],
      [[seed.targets[0], seed.targets[0]], seed.sources, /duplicate_target/],
      [[], seed.sources, /explicit_targets_required/],
    ] as const) {
      await assert.rejects(() => inventoryB17ContentOffline(client, input, sources), error);
      assert.deepEqual(await dataHashes(), before, `${String(error)}: zero business writes`);
      assert.deepEqual(await ledger().then(rows => rows.map(r => r.version)), ['B17_U1'], `${String(error)}: no ledger row`);
    }
    await assert.rejects(() => applyB17ContentOffline(client, { ...inventoryA, beforeHash: 'g2-tampered' }, seed.sources),
      /before_state_drift/, 'tampered before-state refuses the apply');
    await assert.rejects(() => applyB17ContentOffline(client, inventoryA, unknownSource), /source_unknown/,
      'unknown source rows refuse the apply');
    assert.deepEqual(await dataHashes(), before, 'refused applies write nothing');
    pass('OD-10 ambiguous refusal: unknown source/batch/client/duplicate/empty targets + before-state drift all REFUSED, zero writes');

    // ---- Real apply + preservation + idempotence ----
    assert.equal(await applyB17ContentOffline(client, inventoryA, seed.sources), 'applied');
    const dataAfter = await dataHashes(), bindingsAfter = await bindingHashes(), mapsAfter = await maps();
    assert.deepEqual(dataAfter, before, 'every non-binding business row preserved byte-for-byte');
    assert.deepEqual(bindingsAfter, bindingsBefore,
      'esg_profile/report_settings changed ONLY their service_id binding (stripped here)');
    // Bindings did move: the inventoried rows must now point at GRI, nothing else.
    for (const table of BINDING_TABLES) {
      const moved = (await oracle.query(
        `SELECT count(*)::int n FROM ${table} WHERE service_id IS NOT NULL AND service_id <> $1`,
        [inventoryA.serviceId])).rows[0].n;
      assert.equal(moved, 0, `${table}: no row may bind to anything but the GRI service`);
      const bound = (await oracle.query(`SELECT count(*)::int n FROM ${table} WHERE service_id = $1`,
        [inventoryA.serviceId])).rows[0].n;
      assert.ok(bound > 0, `${table}: inventoried rows are bound`);
    }
    const added = mapsAfter.filter(now => !mapsBefore.some(old => old.id === now.id));
    const removed = mapsBefore.filter(old => !mapsAfter.some(now => now.id === old.id));
    assert.deepEqual(removed, [], 'no pre-existing service_standards mapping is removed');
    assert.equal(added.length, inventoryA.standardIds.length, 'exactly the inventoried pairs are added');
    for (const row of added) {
      assert.equal(row.service_id, inventoryA.serviceId, 'added pair targets the GRI service');
      assert.ok(inventoryA.standardIds.includes(row.standard_id), 'added pair standard is inventoried');
    }
    await assert.rejects(() => inventoryB17ContentOffline(client, seed.targets, seed.sources), /already_applied/,
      'post-apply inventory short-circuits on the known content version');
    assert.equal(await applyB17ContentOffline(client, inventoryA, seed.sources), 'verified', 're-apply is idempotent');
    pass('OD-10 apply: preservation (data/bindings/memberships + exact pair additions), already_applied, applied->verified');

    // ---- E1-04: ledger row <-> constant <-> shape <-> live structure ----
    const rows = await ledger();
    const content = rows.find(r => r.version === B17_CONTENT_VERSION);
    assert.ok(content, 'content ledger row exists under the canonical label');
    assert.equal(rows.length, 2, 'ledger is exactly B17_U1 + B17_U2D');
    assert.equal(content.checksum, b17ContentSource().checksum,
      'ledger checksum equals sha256 of the current b17-content.sql');
    assert.equal(content.structure_checksum, B17_CONTENT_SHAPE, 'ledger structure_checksum equals the constant');
    assert.equal(await shape(), B17_CONTENT_SHAPE, 'live STRUCTURE_SQL fingerprint equals the constant');
    await assertB17Ready();
    pass(`E1-04 four-way fresh-apply green: label ${B17_CONTENT_VERSION} <-> ledger <-> ${B17_CONTENT_SHAPE} <-> live`);

    // ---- E1-04 drift REFUSED, restore RECOVERED (each cycle) ----
    const cycles: [string, () => Promise<void>, RegExp][] = [
      ['ledger checksum drift', () => oracle.query(
        "UPDATE app_schema_versions SET checksum=repeat('0',64) WHERE version='B17_U2D'").then(() => undefined),
        /version_drift/],
      ['ledger structure_checksum drift', () => oracle.query(
        "UPDATE app_schema_versions SET structure_checksum=repeat('0',32) WHERE version='B17_U2D'").then(() => undefined),
        /version_drift/],
      ['version label drift', () => oracle.query(
        "UPDATE app_schema_versions SET version='B17_U2E' WHERE version='B17_U2D'").then(() => undefined),
        /version_drift/],
      ['live catalog drift', async () => { await oracle.query('ALTER TABLE clients ADD COLUMN g2_drift_probe int'); }, /schema_drift/],
    ];
    for (const [label, breakIt, error] of cycles) {
      await breakIt();
      await assert.rejects(() => assertB17Ready(), error, `${label} must be REFUSED fail-closed`);
      // Restore the exact pre-drift state.
      if (label === 'live catalog drift') await oracle.query('ALTER TABLE clients DROP COLUMN g2_drift_probe');
      else if (label === 'version label drift') await oracle.query(
        "UPDATE app_schema_versions SET version='B17_U2D' WHERE version='B17_U2E'");
      else if (label === 'ledger checksum drift') await oracle.query(
        'UPDATE app_schema_versions SET checksum=$1 WHERE version=$2',
        [b17ContentSource().checksum, B17_CONTENT_VERSION]);
      else await oracle.query(
        'UPDATE app_schema_versions SET structure_checksum=$1 WHERE version=$2',
        [B17_CONTENT_SHAPE, B17_CONTENT_VERSION]);
      await assertB17Ready();
      assert.equal(await shape(), B17_CONTENT_SHAPE, `${label}: structure restored`);
      pass(`E1-04 ${label}: REFUSED (${String(error)}) then restore RECOVERED (assertB17Ready green)`);
    }
    await verifyB17Content(client);
    pass('E1-04 final verifyB17Content green after every drift/restore cycle');
  } finally { client.release(); }
  console.log('B17 U2-G G2 OD-10 + E1-04 proof complete: dry-run/refusal/preservation/idempotence + four-way '
    + 'consistency with drift-REFUSED/restore-RECOVERED on OWN scratch. NOT release acceptance.');
} finally { await oracle.end().catch(() => {}); await pool.end(); }
